        $scope.deleteRecords = function () {
            var isDelete = false;
            if ($scope.isAllowDelete) {
                if (window["formGroupKeyList"].length > 0) {
                    var deletedList = window["formGroupKeyList"];
                    var param = {};
                    param.action = 3;
                    param.formId = $scope.currentFormId;
                    param.name = $scope.userDetail.name;
                    param.userId = $scope.userDetail.Id;
                    var newDeletedList = [];
                    angular.forEach($scope.selectedDeletedRecordList, function (item) {
                        var created_at = item.created_at;
                        if (item.userID == $scope.userDetail.Id) {
                            if (DataService.isEmpty($scope.formDetailsDataInfo.recordAccessSecurity.own.delete_time) ||
                                $scope.formDetailsDataInfo.recordAccessSecurity.own.delete_time == 0) {
                                newDeletedList.push(item.Id);
                            } else {
                                var deletetime = $scope.formDetailsDataInfo.recordAccessSecurity.own.delete_time;
                                created_at = new Date(created_at);
                                var timeRangeToDelete = add_minutes(created_at, deletetime);
                                var differenceTime = diff_minutes(new Date(), timeRangeToDelete);
                                if (differenceTime <= deletetime && item.userID == $scope.userDetail.Id)
                                    newDeletedList.push(item.Id);
                                else
                                    isDelete = true;
                            }

                        }
                        else if (item.userID != $scope.userDetail.Id) {
                            if (DataService.isEmpty($scope.formDetailsDataInfo.recordAccessSecurity.other.delete_time) ||
                                $scope.formDetailsDataInfo.recordAccessSecurity.other.delete_time == 0) {
                                newDeletedList.push(item.Id);
                            }
                            else {
                                var deletetime = $scope.formDetailsDataInfo.recordAccessSecurity.other.delete_time;
                                created_at = new Date(created_at);
                                var timeRangeToDelete = add_minutes(created_at, deletetime);
                                var differenceTime = diff_minutes(new Date(), timeRangeToDelete);
                                if (differenceTime <= deletetime && item.userID != $scope.userDetail.Id)
                                    newDeletedList.push(item.Id);
                                else
                                    isDelete = true;
                            }
                        }
                    });
                    if (newDeletedList.length > 0) {
                        param.formGroupKeyList = newDeletedList.join();
                        window["formGroupKeyList"] = newDeletedList;
                        //$scope.loadEntryDataIntoTabulatorOnetoMany(param, $scope.formDataForOneParam.formId);
                        if (confirm('Are you sure to delete selected Record?')) {
                            GeneratedFormDataDelete(param);
                        }
                    } else if (isDelete == true && newDeletedList.length == 0) {
                        $timeout(function () {
                            notifierService.notifyMessage('error', 'Delete Time', 'Delete Time is exceed');
                        }, 200);
                    }


                } else {
                    //  alert('Please select atleast one record.')
                    notifierService.notifyMessage('error', 'Form Records', 'Please select atleast one record.');
                }
            } else {
                notifierService.notifyMessage('error', 'Delete Access', 'You have not accessed to delete this form record.');
            }
        };

        $scope.exportAll = function (type) {
            var data = "";
            switch (type) {
                case 1:
                    tabulator.download("json", "data.json");
                    break;
                case 2:
                    tabulator.download("xlsx", "data.xlsx", { sheetName: "sheet1" });
                    break;
                case 3:
                    tabulator.download("csv", "data.csv", { delimiter: "," });
                    break;
                case 4:
                    tabulator.download("pdf", "data.pdf", {
                        orientation: "portrait", //set page orientation to portrait
                        title: "Report", //add title to report
                        autoTable: { //advanced table styling
                            styles: {
                                fillColor: [100, 255, 255]
                            },
                            columnStyles: {
                                id: { fillColor: 255 }
                            },
                            margin: { top: 60 },
                        },
                    });
                    break;
                case 5:
                    data = 1;
                    break;
                default:
                    data = "";
                    break;
            }
        };

