                                    $("tr", table).append("<td align='right'><a class='btn btn-info' onclick=\"angular.element(this).scope().entryPage(" + data.formID + ", true,\'" + data.formGroupKey + "\', \'" + data.Id + "\')\"> Edit </a></td>");

                                    //var data = row.getData();
