        function colorMe() {
            var classnm = ['', 'grid-item--width2', 'grid-item--height2', 'grid-item--width3', 'grid-item--height3'];
            var count = 0;
            $(".grid-item").each(function () {
                var index = $("body").find(".grid-item").index(this);
                var i = (index + count) % classnm.length;
                $(this).addClass(classnm[i]);
            });
            count++;
            console.log('ff')
        }
        function loadPackery() {
            setTimeout(function () {
                $('.grid').packery('destroy');
                var $grid = $('.grid').packery({
                    itemSelector: '.grid-item',
                    gutter: 10,
                    columnWidth: 200,
                    initLayout: false // disable initial layout

                    //percentPosition: true
                });
                Packery.prototype.getShiftPositions = function (attrName) {
                    //console.log(attrName,'attrName')
                    attrName = attrName || 'data-item-id';
                    var _this = this;
                    return this.items.map(function (item) {
                        return {
                            attr: item.element.getAttribute(attrName),
                            x: (item.rect.x != 0) ? (item.rect.x / _this.packer.width) : 0
                        }
                    });
                };

                Packery.prototype.initShiftLayout = function (positions, attr) {
                    if (!positions) {
                        // if no initial positions, run packery layout
                        this.layout();
                        $('.favicon-loader-overlay.active').removeClass('active');
                        return;
                    }
                    // parse string to JSON
                    if (typeof positions == 'string') {
                        try {
                            positions = JSON.parse(positions);
                            // console.log(positions, 'JSON parse')
                            $('.favicon-loader-overlay.active').removeClass('active');
                        } catch (error) {
                            console.error('JSON parse error: ' + error);
                            this.layout();
                            return;
                        }
                    }

                    attr = attr || 'data-item-id'; // default to id attribute
                    this._resetLayout();
                    // set item order and horizontal position from saved positions
                    this.items = positions.map(function (itemPosition) {
                        var selector = '[' + attr + '="' + itemPosition.attr + '"]'
                        var itemElem = this.element.querySelector(selector);
                        var item = this.getItem(itemElem);
                        item.rect.x = itemPosition.x * this.packer.width;
                        return item;
                    }, this);
                    this.shiftLayout();
                    //this.layout();
                };
                $(".grid-item")
                    .draggable({
                        stop: function (event, ui) {
                            $(event.originalEvent.target).one('click', function (e) { e.stopImmediatePropagation(); });
                        },
                        start: function (event, ui) {
                            $(event.originalEvent.target).one('click', function (e) { e.stopImmediatePropagation(); });
                        },
                        drag: function (event, ui) {
                            $(event.originalEvent.target).one('click', function (e) { e.stopImmediatePropagation(); });
                        }
                    })
                $grid.on('click touchstart', '.grid-item', function (event) {
                    event.stopPropagation();
                    // change size of item by toggling large class
                    var $item = $(event.currentTarget);
                    if (event.target.className == "fa fa-eye fa-lg text-darkPrimary") {

                        $item.siblings().find('.fl').addClass('hide');
                        $item.siblings().find('.fl').removeClass('show');
                        $item.siblings().removeClass('grid-item--large');

                        $(event.currentTarget).toggleClass('grid-item--large');
                        if ($item.hasClass('grid-item--large')) {
                            $item.find('.fl').removeClass('hide');
                            $item.find('.fl').addClass('show');
                        }
                        else {
                            $item.find('.fl').removeClass('show');
                            $item.find('.fl').addClass('hide');
                        }
                        $grid.packery('layout');
                        event.stopImmediatePropagation();
                    }
                    else {
                        if (event.type === "click" || event.type === 'touchstart') {
                            //alert();
                            window.location.href = '#/marketplace/' + $item.attr('data-item-id');
                        }
                    }
                });
                var initPositions = localStorage.getItem('dragPositions');
                // init layout with saved positions
                $grid.packery('initShiftLayout', initPositions, 'data-item-id');

                // make all grid-items draggable
                $grid.find('.grid-item').each(function (i, gridItem) {
                    var draggie = new Draggabilly(gridItem);

                    // bind drag events to Packery
                    $grid.packery('bindDraggabillyEvents', draggie);
                });
                $grid.on('dragItemPositioned', function (e) {
                    // save drag positions

                    var positions = $grid.packery('getShiftPositions', 'data-item-id');
                    console.log(e, $grid, positions, 'drag')
                    localStorage.setItem('dragPositions', JSON.stringify(positions));
                });
                colorMe();

            }, 3000);
        }
        $scope.init();
