        function loadTabulator() {
            tabulator = '';
            //$timeout(function () {
            tabulator = initTabulator('userappFormTabulator', {
                groupBy: !DataService.isEmpty($scope.tabulatorConfig.groupBy) ? $scope.tabulatorConfig.groupBy : null,
                height: "530px",
                layout: "fitDataStretch",
                placeholder: "No form found...",
                responsiveLayout: (actionObj ? actionObj['responsive'] : false),
                //selectable: 1,
                columns: $scope.tabulatorHeaders,

                initialSort: [
                    { column: "lastActivityDate", dir: "desc" }
                ],
                footerElement: "<div style='text-align:left' id='no-of-forms'></div>",
                dataLoaded: function (data) {
                    //data - all data loaded into the table
                    var langId = "1";
                    if (localStorage.getItem("globalLangForm") != null && localStorage.getItem("globalLangForm") != 'null') {
                        langId = localStorage.getItem("globalLangForm");
                    }
                    else if (localStorage.getItem("globalLang") != null && localStorage.getItem("globalLang") != 'null') {
                        langId = localStorage.getItem("globalLang");
                    }
                    else {
                        langId = "1";
                    }


                    var count = 0;
                    if (data.length > 0)
                        count = data[0].totalRecords;
                    $('#userappFormTabulator .tabulator-footer #no-of-forms').text(getStringFromMultiligualText("Total|全部的|全部的", langId) + ":" + count + getStringFromMultiligualText("Entries|條目|条目", langId));
                    
                },

                rowClick: function (e, row) {
                    //e - the click event object
                    //row - row component
                    var selectedRows = tabulator.getSelectedRows();
                    //if(selectedRows.length){
                    $('.form-actions').removeClass('disabled hidden');
                    var role = row.getData().userRole;
                    $scope.formOptionDetails = row.getData();
                    if (role != 1) {
                        $('.group-actions').removeClass('disabled hidden');
                    } else {
                        $('.group-actions').addClass('disabled hidden');
                    }
                    //}else{
                    //    $('.group-actions, .form-actions').addClass('disabled hidden');
                    //}
                    if (selectedRows.length) {
                        $('a.user-form-action').removeClass('hidden');
                    } else {
                        $('a.user-form-action').addClass('hidden');
                    }
                },
                cellEdited: function (cell) {
                    var input = [];
                    //input['url'] = "http://192.168.1.141:91/form-generator/public/update_custom";
                    var json = {};
                    var where, columnName = cell.getColumn().getField();
                    if (columnName == "formType") {
                        var formType = parseInt(formTypeId.indexOf(cell.getValue()));
                        if (formType == undefined) {
                            cell.restoreOldValue();
                            alert("User role can't be blank.");
                            return false;
                        }
                        json[columnName] = (formType != undefined ? formType : '');
                        where = { 'formId': cell.getRow().getData().formId };
                    } if (columnName == "formStatus") {
                        var formStatus = parseInt(formStatusId.indexOf(cell.getValue()) + 1);
                        if (formStatus == undefined) {
                            cell.restoreOldValue();
                            alert("User role can't be blank.");
                            return false;
                        }
                        json['status'] = (formStatus != undefined ? formStatus : '');
                        where = { 'formId': cell.getRow().getData().formId };
                    } if (columnName == "groupName") {
                        json['groupID'] = (typeof (dllGroup) === 'undefined') ? 0 : dllGroup;
                        where = { 'formId': cell.getRow().getData().formId };
                    }
                    if (columnName == "formTag" && cell.getRow().getData().created_by == $scope.userDetail.Id) {
                        var txt = cell.getValue();
                        json['field'] = 'substr_check';
                        json[columnName] = cell.getValue();
                        var where = { 'formId': cell.getRow().getData().formId, 'app_id': cell.getRow().getData().applicationID };
                    }
                    if ((columnName == "formTag") && cell.getRow().getData().created_by != $scope.userDetail.Id) {
                        alert("You don't have permission to change this field value!");
                        //cell.setValue("");
                        return false;
                    }
                    //console.log(json);
                    input['data'] = { 'table': 'form', 'update': json, 'where': where };
                    // ajax_call(input);
                    var param = {};
                    param = cell.getRow().getData();
                    //param.publicTemplate = param.publicTemplateText == "No" ? "No" : "Yes";
                    //param.status = changeStatusName(param.StatusName);
                    $scope.onUpdateForm(param);
                },
                ajaxConfig: "POST",
                ajaxContentType: "json",
                ajaxURL: $scope.currentUrl + "/GetFormList",
                ajaxParams: { action: 30, created_by: $scope.userDetail.Id, applicationId: $stateParams.appId },
                ajaxFiltering: true,
                ajaxSorting: true,
                ajaxLoader: true,
                persistentLayout: true,
                persistenceMode: true,
                persistence: {
                    sort: false, //persist column sorting
                    filter: false, //persist filter sorting
                    columns: false, //persist columns
                },
                ajaxProgressiveLoad: "scroll",
                ajaxRequesting: function (url, params) {
                    var called = true;
                    var temp = _.filter(params.filters, function (fltr) {
                        return typeof fltr.value == "object"
                    });
                    if (!DataService.isEmpty(temp)) {
                        if (typeof temp[0].value == "object")
                            called = false;
                    }
                    if (called)
                        $('#userappFormTabulator').block({ message: '<h4>Getting Forms ...</h4>' });
                    return called; //abort ajax request

                },
                ajaxResponse: function (url, params, response) {
                    $('#userappFormTabulator').unblock();
                    setTimeout(function () {
                        jQuery.curCSS = function (element, prop, val) {
                            return jQuery(element).css(prop, val);
                        };
                        $('.showTooltip').bstooltip();
                    }, 500);
                    return response;
                },
                paginationSize: $scope.paginationSizeFormRecords,
            });
            //},10);
        }
        $scope.onGroupByChange = function (data) {
            
            bindTabulatorHeaders(1);
        };
        $scope.init = function () {
            var webActions = '<div class="pull-right text-right rightbtn">\n\
                            <a href="#/" class="btn btn-primary pull-left redirectMenuPage" title="Home"><i class="fa fa-home"></i></a>\n\
                            <a href="#/chat/summary" class="btn btn-primary pull-left chatSummary" title="Chat"><i class="fa fa-commenting"></i ></a >\n\  \n\ </div > ';
            $(".card-header").append(webActions);
            $scope.currentUrl = mainService.getCurrentEndPointUrl();
            //tabulator = $("input[name=tabulator]").val();


            $scope.filterTypeActive = 2;
            $scope.userDetail = mainService.loginDetails();
            $scope.formDetail = {};
            $scope.formDetail.applicationId = "0";
            $scope.getFolderList();
            $scope.groups = {};
            $scope.tabulatorHeaders = [];
            $scope.filterFieldsList = [];
            $scope.tabulatorConfig = {};
            $scope.paginationSizeFormRecords = 30;
            $scope.tabulatorConfiguratorSettings = {};
            if (!DataService.isEmpty(tabulatorConfiguratorSettings.data)) {
                if (tabulatorConfiguratorSettings.data.length > 0) {
                    $scope.tabulatorConfiguratorSettings = tabulatorConfiguratorSettings.data[0];
                }
            }

            bindTabulatorHeaders(0);
            $scope.getApplication();
            $scope.Bindgroup();
            $scope.importFormSettings = { language: 1 };
            $scope.getLanguage();
            $scope.ApplyMultilingualText();


        };
        $scope.setTabulatorGroupBy = function (persistenceID, columnName) {
            $("button[name=group-rows]:not(." + columnName + ")").removeClass("col-hide active");
            $("." + columnName).toggleClass("col-hide active");
            //var $tabulator = $('#' + tabulatorID);
            var cookieName = 'tabulator-grouping-' + persistenceID;

            if ($("." + columnName).hasClass("col-hide")) {
                tabulator.setGroupBy(columnName);
                tabulator.clearSort();
                tabulator.setSort(columnName, "asc");
                $.cookie(cookieName, columnName);
            } else {
                $("." + columnName).removeClass("col-hide active");
                //console.log(typeof tabulator)
                tabulator.setGroupBy(false);
                $.cookie(cookieName, "");
            }
            $('#pageActionModal').modal('hide');
        }
