                //"<a href='" + mainService.getBaseUrl() + "#/chatroom/form_chat/" + cell.getRow().getData().formId + "'  class='showTooltip' title='Start Form Chat'>" +
                //"<i class='fa fa-commenting fa-lg'></i></a> ";

