        $scope.getFunction = function (method) {

            method = (method !== undefined ? method : 'default');
            if ($stateParams.appId.length > 0) {
                $scope.applicationId = $stateParams.appId;
                if (method === "copy-application") {
                    dialog = $ngBootbox.customDialog({
                        //templateUrl: 'copyApplication.html',
                        templateUrl: 'copyall.html',
                        scope: $scope,
                        title: 'Copy Folder',
                        size: "large"
                        //  buttons: $scope.customDialogButtons
                    });

                    $timeout(function () {
                        Waves.attach('.float-buttons', ['waves-button', 'waves-float']);
                        Waves.attach('.flat-buttons', ['waves-button']);
                        Waves.init();
                    }, 250);
                }
                else if (method === "move-forms") {


                    if (tabulator.getSelectedData().length > 0) {
                        $scope.formIds = "";
                        $scope.selectedRows = tabulator.getSelectedData();
                        angular.forEach($scope.selectedRows, function (item) {
                            $scope.formIds = $scope.formIds + item.formId + ",";
                        });
                        console.log($scope.formIds);
                        dialog = $ngBootbox.customDialog({
                            templateUrl: 'moveForms.html',
                            scope: $scope,
                            title: 'Move Forms',
                            size: "large"
                            //  buttons: $scope.customDialogButtons
                        });

                        $timeout(function () {
                            Waves.attach('.float-buttons', ['waves-button', 'waves-float']);
                            Waves.attach('.flat-buttons', ['waves-button']);
                            Waves.init();
                        }, 250);
                    }
                    else {
                        notifierService.notifyMessage('warning', 'Folder', 'Please select atleast one form to move.');
                    }

                }
                else if (method === "copy-selected-forms") {


                    if (tabulator.getSelectedData().length > 0) {
                        $scope.formIds = "";
                        $scope.selectedRows = tabulator.getSelectedData();
                        angular.forEach($scope.selectedRows, function (item) {
                            $scope.formIds = $scope.formIds + item.formId + ",";
                        });
                        console.log($scope.formIds);
                        dialog = $ngBootbox.customDialog({
                            templateUrl: 'copySelectedForms.html',
                            scope: $scope,
                            title: 'Copy Selected Forms',
                            size: "large"
                            //  buttons: $scope.customDialogButtons
                        });

                        $timeout(function () {
                            Waves.attach('.float-buttons', ['waves-button', 'waves-float']);
                            Waves.attach('.flat-buttons', ['waves-button']);
                            Waves.init();
                        }, 250);
                    }
                    else {
                        notifierService.notifyMessage('warning', 'Folder', 'Please select atleast one form to copy.');
                    }

                }

            }
            else {
                notifierService.notifyMessage('warning', 'Folder', 'Please select atleast one folder.');
            }

            return false;
        }
