        $scope.send = function () {
            console.log($scope.userDetails);
            signalR.connectToHub().connection.reconnecting();
            if (!DataService.isEmpty($scope.message)) {
                if ($scope.message.length > 0) {
                    signalR.start(function () {
                        var dt = new Date();
                        var time = dt.getHours() + ":" + dt.getMinutes() + ":" + dt.getSeconds();

                        if (!DataService.isEmpty($scope.roomChatDetails.roomId)) {
                            $scope.paramDetails.message = $scope.message;
                            $scope.paramDetails.ReplyUserId = $scope.roomChatDetails.ReplyUserId;
                            $scope.paramDetails.userId = $scope.userDetails.Id;
                            $scope.paramDetails.roomId = $scope.roomChatDetails.roomId;
                            $scope.paramDetails.chatType = $scope.roomChatDetails.type;
                            $scope.paramDetails.type = $scope.roomChatDetails.type;
                            $scope.paramDetails.filePath = "";
                            $scope.paramDetails.sender = $scope.userDetails.name;
                            $scope.paramDetails.name = $scope.userDetails.name;
                            $scope.paramDetails.userIcon = $scope.userDetails.userIcon;
                            $scope.paramDetails.user_uid = $scope.userDetails.uid;
                            var messageData = $scope.paramDetails;
                            //console.log($scope.roomChatDetails, 'roomChatDetails')
                            //console.log($scope.paramDetails, 'paramDetails')
                            //console.log(messageData, 'messageData')
                            localStorage.setItem($scope.paramDetails.roomId, $scope.roomChatDetails.roomId);
                            signalR.server().send(messageData);
                        }


                    });
                } else {
                    notifierService.notifyMessage('error', 'Message', 'Message is Empty');
                }
            } else {
                notifierService.notifyMessage('error', 'Message', 'Message is Empty');
            }
        };

