        $scope.getRoomChatFunction = function (param) {
            $rootScope.$emit("ShowLoading");
            mainService.getRoomChat("getRAC", param).then(function (response) {
                if (response.data != null && angular.isDefined(response.data)) {
                    $scope.roomChatDetails = {};
                    $scope.roomChatDetails.chatHistory = [];
                    $scope.roomChatDetails = response.data;
                    $scope.activeroom = $scope.roomChatDetails.roomId;
                    localStorage.setItem($scope.roomChatDetails.roomId, $scope.roomChatDetails.roomId);
                    if ($scope.roomChatDetails.res == 1) {
                        //if ($scope.roomChatDetails.type == "user_chat" && !$scope.roomChatDetails.isChat) {
                        //    $state.go('chatSummary');
                        //}
                        if ($scope.roomChatDetails.chatHistory) {
                            if ($scope.roomChatDetails.chatHistory.length > 0) {
                                $scope.chatHistoryTemp = [];
                                $scope.chatHistoryTemp = angular.copy($scope.roomChatDetails.chatHistory);
                                $scope.last = $scope.roomChatDetails.chatHistory[$scope.roomChatDetails.chatHistory.length - 1];
                                $timeout(function () {
                                    $scope.gotoAnchor($scope.last.Id);
                                }, 250);
                                $scope.roomChatDetails.ReplyUserId = $scope.userDetails.Id;
                                //InvitationPopup($scope.roomChatDetails);
                            }
                        }
                    } else {
                        notifierService.notifyMessage('warning', 'Chatting', $scope.roomChatDetails.Message);
                        $state.go("Home", { reload: true, inherit: false });

                    }

                }
                $rootScope.$emit("HideLoading");
            }, function (err) {
                $rootScope.$emit("HideLoading");
                console.log("some error occured." + err);
            });
        };
