        $scope.imgplaceholder = function (imglink) {
            var url = imglink;
            if (url == undefined || url == "" || url == null) {
                url = "newAssets/images/user_geligulu.png";
            }
            var request = new XMLHttpRequest();
            request.open('HEAD', url, false);
            request.send();
            if (request.status == 200) {
                $scope.imglink = true;
                request.abort();
            }
            else {
                $scope.imglink = false;
                url = "newAssets/images/user_geligulu.png";
                request.abort();
            }
            request.abort();
            return url;
        }
        //acceptInvitation message
        $scope.acceptRejectInvitation = function (roomInvitationDetails, status) {
            $scope.paramDetails = {};
            if (!DataService.isEmpty(roomInvitationDetails)) {
                var i = roomInvitationDetails.sender;
                if (roomInvitationDetails.sender.length > 0) {
                    signalR.start(function () {
                        var dt = new Date();
                        var time = dt.getHours() + ":" + dt.getMinutes() + ":" + dt.getSeconds();
                        if (!DataService.isEmpty(roomInvitationDetails.roomId)) {
                            $scope.paramDetails.action = 1;
                            $scope.paramDetails.type = "chatNotify";
                            $scope.paramDetails.UserId = roomInvitationDetails.UserId;
                            $scope.paramDetails.ReplyUserId = roomInvitationDetails.ReplyUserId;
                            $scope.paramDetails.roomId = roomInvitationDetails.roomId;
                            $scope.paramDetails.isInvitationA_R = status;

                            var messageData = $scope.paramDetails;
                            signalR.server().acceptRejectInvitation(messageData);
                            if (status == 1) {
                                $scope.startPrivatechat(roomInvitationDetails);
                            }
                        }
                    });
                } else {
                    notifierService.notifyMessage('error', 'Message', 'Message is Empty');
                }
            } else {
                notifierService.notifyMessage('error', 'Message', 'Message is Empty');
            }
        };

