        function receivedMessagePrivate(chatData) {
            var newChat = chatData;
            var roomId = localStorage.getItem(newChat.roomId);
            if (newChat.roomId == roomId) {
                if ($scope.roomInvitationDetails) {
                    if (!DataService.isEmpty(newChat.message) || !DataService.isEmpty(newChat.filePath)) {
                        $scope.$apply(function () {
                            $scope.roomInvitationDetails.chatHistory.push(newChat);
                            $scope.emessage = "";
                            $scope.searchTextP = "";
                        });
                    }
                }
            }
            $timeout(function () {
                $scope.gotoAnchor(chatData.Id);
            }, 150);
        };


