        function loadEventTabulator() {
            window["tabulators"] = {};
            loadcssjsfile("assets/js/code/form-entry.js", "js", "entryform")
            $rootScope.safeApply();
            $rootScope.$emit("ShowLoading");
            // one to many form control           

            $timeout(function () {
                if ($("#form-table").length) {
                    window["popupTabulator"] = initTabulator("form-table", {
                        columns: [
                            //{ title: "Form", field: "formTitle", sorter: "string", width: 200, editor: true },
                            { title: "Creation Date", field: "created_at", sorter: "date", align: "right" },
                            { title: "Created By", field: "creator_name", sorter: "string" },
                            //{ title: "fieldName", field: "fieldName", align: "center", width: 100 },
                            { title: "From", field: "from_status", sorter: "string" },
                            { title: "To", field: "to_status", sorter: "string", align: "center" },
                            { title: "remarks", field: "remarks", sorter: "string" },
                        ],
                        selectable: $("input[name=multiple_records]").val() !== '1' ? true : 1,
                        cellEdited: function (cell) {
                            //This callback is called any time a cell is edited
                            var columnName = cell.getColumn().getField();
                            var param = {};
                            var formId = $scope.tabuListLink.formId;
                            param.fieldName = columnName;
                            param.formId = formId;
                            param.fieldDataText = "" + cell.getValue().toString() + "";
                            param.Id = cell.getRow().getData().Id;
                            $scope.updateRowDataRecord(param);



                        }

                    });

                }
                var param = {};
                param.action = 4;
                param.formId = $stateParams.formId;
                mainService.manageKanbanHistory("manageKanbanHistory", param)
                    .then(function (response) {
                        //console.log(response);

                        $scope.formDataTabulatorTemp = response.data;
                        $timeout(function () {
                            if ($scope.formDataTabulatorTemp.length > 0)
                                $("#tabulatorModal input[name=formID]").val($stateParams.formId);
                            window["popupTabulator"].setHeight("450px");
                            //window["popupTabulator"].setColumns({ title: "Form Tags", headerFilter: true, field: "formId", editor: true, width: 150 });
                            window["popupTabulator"].setData($scope.formDataTabulatorTemp);
                            $rootScope.$emit("HideLoading");
                        }, 150);
                    }, function (err) {
                        $rootScope.$emit("HideLoading");
                        //console.log("some error occured." + err);
                    });
            }, 450);

        };

