    FormGeneratorApp.controller('paymentCheckoutController', function ($scope, $rootScope, $http, $timeout, $location, $window, DataService, notifierService, mainService, $ngBootbox, $stateParams) {
        $scope.init = function () {
            showLoader("#output");
            $rootScope.$emit("ShowLoading");
            $scope.userDetails = mainService.loginDetails();
            var planId = $stateParams.planId;
            $scope.paidplan = $stateParams.paidplan;
            $scope.topicId = $stateParams.topicId;
            $scope.paymentParam = {};
            $scope.planId = planId;
            $scope.getPlanDetails();
        };
        $scope.getPlanDetails = function () {
            var param = {};
            param.action = 7;
            param.Id = $scope.planId;
            $rootScope.$emit("ShowLoading");

            mainService.ManageSubscriptionModelDetails("ManageSubscriptionModelDetails", param)
                .then(function (response) {
                    if (response.data != null && angular.isDefined(response.data)) {
                        var data = response.data;
                        console.log(data);
                        if (data.length > 0) {

                            $scope.paymentParamDetails = data[0];
                            var tokenParam = {};
                            // tokenParam.PAYMENTREQUEST_0_AMT = "20";
                            tokenParam.METHOD = "SetExpressCheckOut";
                            if ($scope.paidplan == "Monthly") {
                                tokenParam.PAYMENTREQUEST_0_AMT = $scope.paymentParamDetails.PerMonthPrice;
                            }
                            else if ($scope.paidplan == "Yearly") {
                                tokenParam.PAYMENTREQUEST_0_AMT = $scope.paymentParamDetails.PerYearPrice;
                            }
                            tokenParam.RETURNURL = mainService.getBaseUrl() + "#/paymentProcess";
                            tokenParam.CANCELURL = mainService.getBaseUrl() + "#/paymentProcess";
                            tokenParam.action = 1;
                            tokenParam.planId = $scope.planId;
                            tokenParam.paidplan = $scope.paidplan;
                            tokenParam.UserId = $scope.userDetails.Id;
                            tokenParam.topicId = $scope.topicId;
                            gettoken(tokenParam, param);
                        }
                    }
                    $rootScope.$emit("HideLoading");
                }, function (err) {
                    $rootScope.$emit("HideLoading");
                    console.log("some error occured." + err);
                });
        }

        function gettoken(tokenParam, param) {
            $rootScope.$emit("ShowLoading");
            mainService.getPaypalToken("getTokenPay", tokenParam)
                .then(function (response) {
                    if (response.data != null && angular.isDefined(response.data)) {
                        var data = response.data;
                        data.planId = $scope.planId;
                        data.userId = param.userId;
                        data.PAYMENTREQUEST_0_AMT = tokenParam.PAYMENTREQUEST_0_AMT;
                        localStorage.setItem("tokenp", JSON.stringify(data))
                        //console.log(data);
                        window.location.href = data.retMsg;
                    }
                    $rootScope.$emit("HideLoading");
                }, function (err) {
                    $rootScope.$emit("HideLoading");
                    console.log("some error occured." + err);
                });
        }
        $scope.updatePaymentDetails = function (param) {
            var paramData = {};

            paramData = param;
            paramData.action = 1;
            paramData.TopicId = topicId
            $rootScope.$emit("ShowLoading");
            mainService.managePayPaltransaction("ManageSubscriptionModelForTopic", paramData)
                .then(function (response) {
                    console.log(response, 'response');
                    if (response.data != null && angular.isDefined(response.data)) {

                        $rootScope.$emit("HideLoading");

                        $scope.exists = response.data;
                        console.log($scope.exists, 'sona');
                        if ($scope.exists.res == 1) {
                            $state.go('topic', { reload: true });

                        }


                    }
                }, function (err) {
                    $rootScope.$emit("HideLoading");
                    console.log("some error occured." + err);
                });
        }
        $scope.init();
    });
